program:
f(x: u16) = x ^ x
g(x: u16) = x ^ x where x in {0,1,2,3}
equiv f g

p(x: u16) = x
q(x: u16) = x where x in {0,1,2,3}
equiv p ~q

u(x: u16) = x * 1
v(x: u16) = x * 1 where x in {0,1,2,3}
equiv u v

a(x: u8) = x + 0
b(x: u8) = x + 0 where x in {0,1,2,3}
equiv a ~b

id1(x: u16) = x ^ x
id2(x: u16) = x ^ x where x in {0,1,2,3}
equiv id1 ~id2

fa(x: i8) = 0 + x
ga(x: i8) = 0 + x where x in {-128,-127,-126,-125}
equiv fa ga

lo(x: i8) = x - 0
hi(x: i8) = x - 0 where x in {-128,-127,-126,-125}
equiv lo ~hi

fn(a: f64, b: f64) = (a+b)*(a-b)
gn(a: f64, b: f64) = a^2 - b^2
equiv fn ~ gn

fn(a: f64, b: f64) = (a+b)*(a-b)
gn(a: f64, b: f64) = a^2 - b^2
equiv fn ~ gn

fn(a: f32, b: f32) = (a+b)*(a-b)
gn(a: f32, b: f32) = a^2 - b^2
equiv fn ~ gn
